import math
def control(obs):
    lm=obs.get('local_map',{})
    def interp(points,x):
        p=sorted((a,b) for a,b in points if a>-1)
        for i in range(len(p)-1):
            if p[i][0]<=x<=p[i+1][0] and p[i+1][0]-p[i][0]>0.01:
                q=(x-p[i][0])/(p[i+1][0]-p[i][0]); return p[i][1]*(1-q)+p[i+1][1]*q
        return None
    l=lm.get('left_rail',[]); r=lm.get('right_rail',[])
    target=None
    for x in (5.0,4.0,3.0,2.0):
        a=interp(l,x); b=interp(r,x)
        if a is not None and b is not None:
            target=(x,(a+b)/2); break
    h=obs.get('hitch_deg',0)
    if target:
        x,y=target
        desired=max(-24,min(24,math.degrees(math.atan2(y,x))*1.1))
    else: desired=0
    steer=max(-34,min(34,2.2*(h-desired)))
    return (steer,-0.8,180)

