    def at(points,x):
        p=sorted((a,b) for a,b in points if a>-1)
        for i in range(len(p)-1):
            if p[i][0]<=x<=p[i+1][0]:
                a,b=p[i]; c,d=p[i+1]; return b+(d-b)*(x-a)/(c-a)
        return None
    left=m.get('left_rail',[]); right=m.get('right_rail',[])
    vals=[]
    for x in (3.0,5.0,7.0):
        l=at(left,x); r=at(right,x)
