    target=sum(v*(1 if x<6 else 0.7) for x,v in vals)/sum((1 if x<6 else 0.7) for x,v in vals) if vals else 0
    desired=max(-16,min(16,target*5))
    hitch=obs.get('hitch_deg',0)
    steer=max(-40,min(40,2.0*(hitch-desired)))
    return steer,-0.7,180

