import math

def control(obs):
    m=obs.get('local_map',{})
    left=m.get('left_rail',[])
    right=m.get('right_rail',[])
    def interp(points,x):
        pts=sorted((p[0],p[1]) for p in points if len(p)>=2)
        for a,b in zip(pts,pts[1:]):
            if a[0]<=x<=b[0] and b[0]>a[0]:
                return a[1]+(b[1]-a[1])*(x-a[0])/(b[0]-a[0])
        return None
    centers=[]
    for x in (3,6,9,12,15,18):
        l=interp(left,x); r=interp(right,x)
        if l is not None and r is not None:
            centers.append((x,(l+r)/2))
    h=obs.get('hitch_deg',0)
    if centers:
        x,y=centers[-1]
        target=max(-12,min(12,math.degrees(math.atan2(y,x))*1.5))
    else:
        target=0
    steer=max(-35,min(35,2.0*(h-target)))
    return steer,-0.8,180

